"""Dedicated greedy decode tail for canonical BF16 logits.

The kernel reduces one contiguous logits row across several CTAs.  Each CTA
publishes a packed local winner, and the last arrival writes both scheduler
destinations.  The packed ordering preserves torch's first-index and
first-NaN argmax behavior without converting BF16 values to FP32.
"""

import cutlass
import cutlass.cute as cute
import cuda.bindings.driver as cuda
from cutlass import Int32, Int64, const_expr
from cutlass.cutlass_dsl import T, dsl_user_op
from cutlass._mlir.dialects import llvm


@dsl_user_op
def _load_bf16x8_words(gmem_ptr: cute.Pointer, *, loc=None, ip=None):
    result = llvm.inline_asm(
        llvm.StructType.get_literal([T.i32(), T.i32(), T.i32(), T.i32()]),
        [gmem_ptr.toint(loc=loc, ip=ip).ir_value()],
        "ld.global.v4.b32 {$0, $1, $2, $3}, [$4];",
        "=r,=r,=r,=r,l",
        has_side_effects=True,
        loc=loc,
        ip=ip,
    )
    return (
        Int32(llvm.extractvalue(T.i32(), result, [0], loc=loc, ip=ip)),
        Int32(llvm.extractvalue(T.i32(), result, [1], loc=loc, ip=ip)),
        Int32(llvm.extractvalue(T.i32(), result, [2], loc=loc, ip=ip)),
        Int32(llvm.extractvalue(T.i32(), result, [3], loc=loc, ip=ip)),
    )


@dsl_user_op
def _atomic_max_release_u64(
    value: Int64, gmem_ptr: cute.Pointer, *, loc=None, ip=None
) -> Int64:
    old = llvm.inline_asm(
        T.i64(),
        [
            gmem_ptr.toint(loc=loc, ip=ip).ir_value(),
            Int64(value).ir_value(loc=loc, ip=ip),
        ],
        "atom.global.max.release.gpu.u64 $0, [$1], $2;",
        "=l,l,l",
        has_side_effects=True,
        is_align_stack=False,
        asm_dialect=llvm.AsmDialect.AD_ATT,
        loc=loc,
        ip=ip,
    )
    return Int64(old)


@dsl_user_op
def _atomic_add_acq_rel_i32(
    value: Int32, gmem_ptr: cute.Pointer, *, loc=None, ip=None
) -> Int32:
    old = llvm.inline_asm(
        T.i32(),
        [
            gmem_ptr.toint(loc=loc, ip=ip).ir_value(),
            Int32(value).ir_value(loc=loc, ip=ip),
        ],
        "atom.global.add.acq_rel.gpu.s32 $0, [$1], $2;",
        "=r,l,r",
        has_side_effects=True,
        is_align_stack=False,
        asm_dialect=llvm.AsmDialect.AD_ATT,
        loc=loc,
        ip=ip,
    )
    return Int32(old)


@dsl_user_op
def _load_acquire_u64(
    gmem_ptr: cute.Pointer, *, loc=None, ip=None
) -> Int64:
    value = llvm.inline_asm(
        T.i64(),
        [gmem_ptr.toint(loc=loc, ip=ip).ir_value()],
        "ld.global.acquire.gpu.u64 $0, [$1];",
        "=l,l",
        has_side_effects=True,
        is_align_stack=False,
        asm_dialect=llvm.AsmDialect.AD_ATT,
        loc=loc,
        ip=ip,
    )
    return Int64(value)


@dsl_user_op
def _atomic_exch_release_u64(
    value: Int64, gmem_ptr: cute.Pointer, *, loc=None, ip=None
) -> None:
    llvm.inline_asm(
        T.i64(),
        [
            gmem_ptr.toint(loc=loc, ip=ip).ir_value(),
            Int64(value).ir_value(loc=loc, ip=ip),
        ],
        "atom.global.exch.release.gpu.b64 $0, [$1], $2;",
        "=l,l,l",
        has_side_effects=True,
        is_align_stack=False,
        asm_dialect=llvm.AsmDialect.AD_ATT,
        loc=loc,
        ip=ip,
    )


@dsl_user_op
def _atomic_exch_release_i32(
    value: Int32, gmem_ptr: cute.Pointer, *, loc=None, ip=None
) -> None:
    llvm.inline_asm(
        T.i32(),
        [
            gmem_ptr.toint(loc=loc, ip=ip).ir_value(),
            Int32(value).ir_value(loc=loc, ip=ip),
        ],
        "atom.global.exch.release.gpu.b32 $0, [$1], $2;",
        "=r,l,r",
        has_side_effects=True,
        is_align_stack=False,
        asm_dialect=llvm.AsmDialect.AD_ATT,
        loc=loc,
        ip=ip,
    )


@cute.jit
def _bf16_rank(raw: Int32) -> Int32:
    """Map one BF16 bit pattern to an integer argmax ordering."""

    raw = raw & Int32(0xFFFF)
    magnitude = raw & Int32(0x7FFF)
    if magnitude == Int32(0):
        # torch treats -0 and +0 as equal, so normalize before ranking.
        raw = Int32(0)
    exponent = raw & Int32(0x7F80)
    mantissa = raw & Int32(0x007F)
    rank = raw ^ Int32(0x8000)
    if exponent == Int32(0x7F80) and mantissa != Int32(0):
        rank = Int32(0x1FFFF)
    elif (raw & Int32(0x8000)) != Int32(0):
        rank = (~raw) & Int32(0xFFFF)
    return rank


@cute.jit
def _choose_rank_index(
    rank: Int32,
    index: Int32,
    candidate_rank: Int32,
    candidate_index: Int32,
):
    if candidate_rank > rank or (
        candidate_rank == rank and candidate_index < index
    ):
        rank = candidate_rank
        index = candidate_index
    return rank, index


@cute.jit
def _warp_reduce_rank_index(rank: Int32, index: Int32):
    for offset in (16, 8, 4, 2, 1):
        candidate_rank = cute.arch.shuffle_sync_bfly(rank, offset=offset)
        candidate_index = cute.arch.shuffle_sync_bfly(index, offset=offset)
        rank, index = _choose_rank_index(
            rank, index, candidate_rank, candidate_index
        )
    return rank, index


@cute.jit
def _element_pointer(tensor: cute.Tensor, coord) -> cute.Pointer:
    return tensor.iterator + cute.crd2idx(coord, tensor.layout)


class GreedyTail:
    """One-launch BF16 argmax plus scheduler pending-token scatter."""

    # Tried one 1024-thread CTA per B8 row: 51.245 us versus torch's
    # 12.448 us argmax; keeping the multi-CTA last-arrival reduction.

    def __init__(
        self,
        vocab_size: int,
        *,
        num_threads: int = 256,
        num_splits: int = 32,
    ) -> None:
        if vocab_size <= 0 or vocab_size % 8 != 0:
            raise ValueError("GreedyTail requires a positive vocab divisible by 8")
        if num_threads < 32 or num_threads > 1024 or num_threads % 32 != 0:
            raise ValueError("num_threads must be a warp multiple in [32, 1024]")
        if num_splits <= 0:
            raise ValueError("num_splits must be positive")
        self.vocab_size = vocab_size
        self.num_threads = num_threads
        self.num_warps = num_threads // 32
        self.num_splits = num_splits

    @cute.jit
    def __call__(
        self,
        sampled_ids: cute.Tensor,
        pending_token_ids: cute.Tensor,
        logits: cute.Tensor,
        batch_indices: cute.Tensor,
        winner_keys: cute.Tensor,
        completion_counters: cute.Tensor,
        stream: cuda.CUstream,
    ) -> None:
        rows = logits.shape[0]
        self.kernel(
            sampled_ids,
            pending_token_ids,
            logits,
            batch_indices,
            winner_keys,
            completion_counters,
        ).launch(
            grid=[rows * self.num_splits, 1, 1],
            block=[self.num_threads, 1, 1],
            stream=stream,
        )

    @cute.kernel
    def kernel(
        self,
        sampled_ids: cute.Tensor,
        pending_token_ids: cute.Tensor,
        logits: cute.Tensor,
        batch_indices: cute.Tensor,
        winner_keys: cute.Tensor,
        completion_counters: cute.Tensor,
    ) -> None:
        tidx, _, _ = cute.arch.thread_idx()
        block, _, _ = cute.arch.block_idx()
        row = block // Int32(self.num_splits)
        split = block - row * Int32(self.num_splits)
        lane = tidx % Int32(32)
        warp = tidx // Int32(32)

        @cute.struct
        class SharedStorage:
            ranks: cute.struct.Align[
                cute.struct.MemRange[Int32, self.num_warps], 16
            ]
            indices: cute.struct.Align[
                cute.struct.MemRange[Int32, self.num_warps], 16
            ]

        storage = cutlass.utils.SmemAllocator().allocate(SharedStorage, 16)
        warp_ranks = storage.ranks.get_tensor(
            cute.make_layout((self.num_warps,))
        )
        warp_indices = storage.indices.get_tensor(
            cute.make_layout((self.num_warps,))
        )

        vector_count = const_expr(self.vocab_size // 8)
        vectors_per_split = const_expr(
            (vector_count + self.num_splits - 1) // self.num_splits
        )
        vector_begin = split * Int32(vectors_per_split)
        vector_end = vector_begin + Int32(vectors_per_split)
        if vector_end > Int32(vector_count):
            vector_end = Int32(vector_count)

        ranks = cute.make_rmem_tensor((8,), Int32)
        indices = cute.make_rmem_tensor((8,), Int32)
        ranks.fill(0)
        indices.fill(0x7FFFFFFF)
        vector = vector_begin + tidx
        while vector < vector_end:
            element = vector * Int32(8)
            words = _load_bf16x8_words(
                _element_pointer(logits, (row, element))
            )
            for pair in cutlass.range_constexpr(4):
                word = words[pair]
                lo_raw = word & Int32(0xFFFF)
                hi_raw = (word >> Int32(16)) & Int32(0xFFFF)
                lo_slot = pair * 2
                hi_slot = lo_slot + 1
                lo_rank = _bf16_rank(lo_raw)
                hi_rank = _bf16_rank(hi_raw)
                if lo_rank > ranks[lo_slot]:
                    ranks[lo_slot] = lo_rank
                    indices[lo_slot] = element + Int32(lo_slot)
                if hi_rank > ranks[hi_slot]:
                    ranks[hi_slot] = hi_rank
                    indices[hi_slot] = element + Int32(hi_slot)
            vector += Int32(self.num_threads)

        rank = Int32(0)
        index = Int32(0x7FFFFFFF)
        for slot in cutlass.range_constexpr(8):
            rank, index = _choose_rank_index(
                rank, index, ranks[slot], indices[slot]
            )
        rank, index = _warp_reduce_rank_index(rank, index)
        if lane == Int32(0):
            warp_ranks[warp] = rank
            warp_indices[warp] = index
        cute.arch.sync_threads()

        if warp == Int32(0):
            rank = Int32(0)
            index = Int32(0x7FFFFFFF)
            if lane < Int32(self.num_warps):
                rank = warp_ranks[lane]
                index = warp_indices[lane]
            rank, index = _warp_reduce_rank_index(rank, index)
            if lane == Int32(0):
                key = (
                    (Int64(rank) << Int64(32))
                    | (Int64(0xFFFFFFFF) - Int64(index))
                )
                winner_ptr = _element_pointer(winner_keys, row)
                counter_ptr = _element_pointer(completion_counters, row)
                _atomic_max_release_u64(key, winner_ptr)
                old = _atomic_add_acq_rel_i32(Int32(1), counter_ptr)
                if old == Int32(self.num_splits - 1):
                    winner = _load_acquire_u64(winner_ptr)
                    token = Int64(0xFFFFFFFF) - (
                        winner & Int64(0xFFFFFFFF)
                    )
                    sampled_ids[row] = token
                    pending_index = Int64(batch_indices[row])
                    if (
                        pending_index >= Int64(0)
                        and pending_index < Int64(pending_token_ids.shape[0])
                    ):
                        pending_token_ids[pending_index] = token
                    _atomic_exch_release_u64(Int64(0), winner_ptr)
                    _atomic_exch_release_i32(Int32(0), counter_ptr)


__all__ = ["GreedyTail"]
